package app.streamnest;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
final class RemoveContinueRegression {
 static Button find(View root){if(root instanceof Button&&String.valueOf(root.getContentDescription()).startsWith("Remove Synthetic Removal"))return (Button)root;if(root instanceof ViewGroup)for(int n=0;n<((ViewGroup)root).getChildCount();n++){Button b=find(((ViewGroup)root).getChildAt(n));if(b!=null)return b;}return null;}
 static Bundle run(Instrumentation test)throws Exception{Context c=test.getTargetContext();String previous=WatchProgress.preferenceName;boolean pending=WatchSync.pending;MainActivity[] activity={null};WatchProgress.preferenceName="remove-continue-test";WatchSync.pending=true;
 try{c.getSharedPreferences(WatchProgress.preferenceName,0).edit().clear().commit();long now=System.currentTimeMillis()-1000;JSONObject stale=new JSONObject().put("episode:tt99999999:1:1",new JSONObject().put("positionMs",12000).put("durationMs",120000).put("updatedAt",now)).put("episode:tt99999999:2:3",new JSONObject().put("positionMs",30000).put("durationMs",120000).put("updatedAt",now+1));WatchProgress.merge(c,stale);
 Catalog.Title title=Catalog.parse(new JSONObject().put("imdb","tt99999999").put("title","Synthetic Removal").put("year",2020),"shows");java.util.List<HomeFeed.Row> rows=HomeFeed.build(Arrays.asList(title),WatchProgress.records(c),12);HomeRegression.check(rows.get(0).cards.size()==1,"Missing starting Continue card");
 activity[0]=(MainActivity)test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(700);test.runOnMainSync(()->{activity[0].renderHome(rows);Button button=find(activity[0].getWindow().getDecorView());HomeRegression.check(button!=null&&button.isFocusable(),"Accessible Remove button missing");button.performClick();});
 HomeRegression.check(WatchProgress.read(c,"episode:tt99999999:2:3",30000)==0,"Legacy timestamp restored after removal");HomeRegression.check(!c.getSharedPreferences(WatchProgress.preferenceName,0).contains("episode:tt99999999:1:1"),"Earlier episode timestamp remains stored");WatchProgress.merge(c,stale);HomeRegression.check(HomeFeed.build(Arrays.asList(title),WatchProgress.records(c),12).get(0).cards.isEmpty(),"Stale synced history resurrected card");
 WatchProgress.save(c,"episode:tt99999999:1:1",20000,120000);HomeRegression.check(WatchProgress.read(c,"episode:tt99999999:1:1",0)==20000,"Fresh playback cannot resume");Bundle result=new Bundle();result.putString("result","PASS: native accessible Remove action clears all episode timestamps and legacy resume; stale group merge cannot restore; fresh playback returns");return result;
 }finally{if(activity[0]!=null)test.runOnMainSync(()->activity[0].finish());c.getSharedPreferences(WatchProgress.preferenceName,0).edit().clear().commit();WatchProgress.preferenceName=previous;WatchSync.pending=pending;WatchSync.followup=false;}}
}
